-- Add the reader-provided Kasai and Hojo Railway photos to both language editions.
update public.posts
set
  content = replace(
    replace(
      replace(
        replace(
          replace(
            content,
            'আরও কাছে গিয়ে জানতে পারলাম, এটি [Kasai City Global Center](https://kasai-globalcenter.jp/)—জাপানি নাম **加西市グローバルセンター**।',
            E'আরও কাছে গিয়ে জানতে পারলাম, এটি [Kasai City Global Center](https://kasai-globalcenter.jp/)—জাপানি নাম **加西市グローバルセンター**।\n\n![Kasai City Global Center-এর অভ্যন্তর](https://halimslife.com/images/blog/kasai-global-center-interior.webp)\n\n_ছবিতে Kasai City Global Center-এর ভেতরের স্বাগত ডেস্ক—যে জায়গাটি এখন আমার কাছে খুব পরিচিত।_'
          ),
          'আর Kasai City Global Center-এর সঙ্গেও আমার সম্পর্ক সেই প্রথম বিস্ময়ের দিনে শেষ হয়ে যায়নি। কেন্দ্রটির বিভিন্ন অনুষ্ঠান ও আয়োজন, এবং নানা মানুষের সঙ্গে মিলিত হওয়ার উষ্ণ পরিবেশ আমার খুব ভালো লাগে। **প্রতি সপ্তাহান্তেই আমি সেখানে যাই।** প্রতিবারই মনে হয়, পৃথিবীর নানা দেশের মানুষকে একে অন্যের কাছে আনার যে বার্তা সেই পতাকাটি দিয়েছিল, কেন্দ্রটি এখনো সেই বার্তাকে বাস্তবে রূপ দিয়ে চলেছে।',
          E'আর Kasai City Global Center-এর সঙ্গেও আমার সম্পর্ক সেই প্রথম বিস্ময়ের দিনে শেষ হয়ে যায়নি। কেন্দ্রটির বিভিন্ন অনুষ্ঠান ও আয়োজন, এবং নানা মানুষের সঙ্গে মিলিত হওয়ার উষ্ণ পরিবেশ আমার খুব ভালো লাগে। **প্রতি সপ্তাহান্তেই আমি সেখানে যাই।** প্রতিবারই মনে হয়, পৃথিবীর নানা দেশের মানুষকে একে অন্যের কাছে আনার যে বার্তা সেই পতাকাটি দিয়েছিল, কেন্দ্রটি এখনো সেই বার্তাকে বাস্তবে রূপ দিয়ে চলেছে।\n\n![Kasai City Global Center-এর বহুসাংস্কৃতিক অনুষ্ঠান](https://halimslife.com/images/blog/kasai-global-center-community-event.webp)\n\n_ছবিতে কেন্দ্রটির একটি বহুসাংস্কৃতিক আয়োজন—বিভিন্ন দেশের মানুষ, খাবার আর গল্পে ভরা উষ্ণ এক মিলনমেলা।_'
        ),
        'পরে কাসাই সম্পর্কে জানতে গিয়ে বুঝেছি, সেদিনের সেই শান্ত দৃশ্যটি কাসাইয়ের পরিচয়েরই অংশ। এই শহরের মধ্য দিয়ে চলে যাওয়া **Hojo Railway** ১৯১৫ সালে যাত্রা শুরু করে। এক লাইনের এই লোকাল রেলপথ মোট ১৩.৬ কিলোমিটার দূরত্বে আটটি স্টেশনকে যুক্ত করেছে। Hojomachi ছাড়া বাকি স্টেশনগুলো জনবলহীন। এক কামরার ছোট ট্রেনটি ধানখেত ও গ্রামীণ প্রকৃতির ভেতর দিয়ে যায়—মনে হয়, সময়ও যেন তার সঙ্গে ধীর হয়ে যায়।',
        E'পরে কাসাই সম্পর্কে জানতে গিয়ে বুঝেছি, সেদিনের সেই শান্ত দৃশ্যটি কাসাইয়ের পরিচয়েরই অংশ। এই শহরের মধ্য দিয়ে চলে যাওয়া **Hojo Railway** ১৯১৫ সালে যাত্রা শুরু করে। এক লাইনের এই লোকাল রেলপথ মোট ১৩.৬ কিলোমিটার দূরত্বে আটটি স্টেশনকে যুক্ত করেছে। Hojomachi ছাড়া বাকি স্টেশনগুলো জনবলহীন। এক কামরার ছোট ট্রেনটি ধানখেত ও গ্রামীণ প্রকৃতির ভেতর দিয়ে যায়—মনে হয়, সময়ও যেন তার সঙ্গে ধীর হয়ে যায়।\n\n![কাসাইয়ের গ্রামীণ স্টেশনে Hojo Railway-এর সবুজ ট্রেন](https://halimslife.com/images/blog/kasai-hojo-train-rural-station.webp)\n\n_কাসাইয়ের গ্রামীণ স্টেশনে Hojo Railway-এর সবুজ এক কামরার ট্রেন।_'
      ),
      'ট্রেনের জানালা থেকে দেখা যায় শস্যক্ষেত্র, নিরিবিলি প্রকৃতি আর Zenbo ও Kasamatsu পাহাড়—যেগুলোকে একসঙ্গে **Kasai Alps** বলা হয়। পাহাড়ে হাইকিংয়ের পথও আছে। আর Hojōchō এলাকায় রয়েছে ১,৩০০ বছরেরও বেশি পুরোনো Sumiyoshi Shrine, Sagamiji Temple এবং রহস্যময় **500 Rakan** পাথরের মূর্তি। পুরোনো post-town ও temple-town হিসেবে গড়ে ওঠা এলাকাটির পথঘাটে হাঁটলে জাপানের পুরোনো সময়ের আমেজ এখনও অনুভব করা যায়।',
      E'ট্রেনের জানালা থেকে দেখা যায় শস্যক্ষেত্র, নিরিবিলি প্রকৃতি আর Zenbo ও Kasamatsu পাহাড়—যেগুলোকে একসঙ্গে **Kasai Alps** বলা হয়। পাহাড়ে হাইকিংয়ের পথও আছে। আর Hojōchō এলাকায় রয়েছে ১,৩০০ বছরেরও বেশি পুরোনো Sumiyoshi Shrine, Sagamiji Temple এবং রহস্যময় **500 Rakan** পাথরের মূর্তি। পুরোনো post-town ও temple-town হিসেবে গড়ে ওঠা এলাকাটির পথঘাটে হাঁটলে জাপানের পুরোনো সময়ের আমেজ এখনও অনুভব করা যায়।\n\n![Hojomachi Station-এ Hojo Railway-এর রঙিন ট্রেন](https://halimslife.com/images/blog/kasai-hojo-trains-hojomachi.webp)\n\n_Hojomachi Station-এ পাশাপাশি দাঁড়িয়ে থাকা Hojo Railway-এর রঙিন ট্রেন।_'
    ),
    'এসব তথ্য পড়ে সেদিনের হাঁটাটিকে যেন আরও নতুনভাবে দেখতে পারি। যে নীরবতা প্রথমে আমার কাছে নিছক একটি দূরবর্তী গ্রামীণ শহরের নীরবতা মনে হয়েছিল, তার ভেতরেই লুকিয়ে আছে কাসাইয়ের রেলগাথা, ইতিহাস আর মানুষের ভালোবাসা। কাসাই ভ্রমণের আরও বিস্তারিত তথ্য পাওয়া যাবে [Visit HYOGO-এর অফিসিয়াল ভ্রমণ নিবন্ধে](https://www.hyogo-tourism.jp/world/feature/detail_109.html)।',
    E'এসব তথ্য পড়ে সেদিনের হাঁটাটিকে যেন আরও নতুনভাবে দেখতে পারি। যে নীরবতা প্রথমে আমার কাছে নিছক একটি দূরবর্তী গ্রামীণ শহরের নীরবতা মনে হয়েছিল, তার ভেতরেই লুকিয়ে আছে কাসাইয়ের রেলগাথা, ইতিহাস আর মানুষের ভালোবাসা। কাসাই ভ্রমণের আরও বিস্তারিত তথ্য পাওয়া যাবে [Visit HYOGO-এর অফিসিয়াল ভ্রমণ নিবন্ধে](https://www.hyogo-tourism.jp/world/feature/detail_109.html)।\n\n![কাসাইয়ের স্টেশনে Hojo Railway-এর লাল ট্রেন](https://halimslife.com/images/blog/kasai-hojo-red-train-station.webp)\n\n_শান্ত কাসাই শহরের পথে Hojo Railway-এর লাল-গোলাপি ট্রেন—এই শহরের চেনা, প্রিয় একটি দৃশ্য।_'
  ),
  updated_at = now()
where slug = 'bangladesh-flag-at-kasai-global-center'
  and content not like '%kasai-global-center-interior.webp%';

update public.posts
set
  content = replace(
    replace(
      replace(
        replace(
          replace(
            content,
            '近づいて分かったのは、そこが [加西市グローバルセンター](https://kasai-globalcenter.jp/) だということでした。',
            E'近づいて分かったのは、そこが [加西市グローバルセンター](https://kasai-globalcenter.jp/) だということでした。\n\n![加西市グローバルセンターの館内](https://halimslife.com/images/blog/kasai-global-center-interior.webp)\n\n_加西市グローバルセンターの受付。今では私にとって、とても親しみのある場所です。_'
          ),
          'グローバルセンターとの関わりも、あの日の驚きだけで終わりませんでした。センターのさまざまなイベントや、国籍や文化の異なる人たちと出会える温かな雰囲気が好きで、 **毎週末、センターに足を運んでいます。** 訪れるたびに、あの国旗から感じた「人と人をつなぐ」というメッセージが、ここで今も形になっていると感じます。',
          E'グローバルセンターとの関わりも、あの日の驚きだけで終わりませんでした。センターのさまざまなイベントや、国籍や文化の異なる人たちと出会える温かな雰囲気が好きで、 **毎週末、センターに足を運んでいます。** 訪れるたびに、あの国旗から感じた「人と人をつなぐ」というメッセージが、ここで今も形になっていると感じます。\n\n![加西市グローバルセンターの多文化交流イベント](https://halimslife.com/images/blog/kasai-global-center-community-event.webp)\n\n_加西市グローバルセンターの多文化交流イベント。さまざまな国の人たちが、料理と会話を楽しむ温かなひとときです。_'
        ),
        '後に加西市について知るうちに、あの日に見た穏やかな風景こそ、このまちの魅力の一部なのだと分かりました。加西市を走る **北条鉄道** は1915年に開業し、全長13.6キロの区間で8つの駅を結んでいます。北条町駅以外は無人駅で、一両編成の小さな列車が田畑と里山の景色の中を進む姿は、時間までゆっくりと流れているように感じられます。',
        E'後に加西市について知るうちに、あの日に見た穏やかな風景こそ、このまちの魅力の一部なのだと分かりました。加西市を走る **北条鉄道** は1915年に開業し、全長13.6キロの区間で8つの駅を結んでいます。北条町駅以外は無人駅で、一両編成の小さな列車が田畑と里山の景色の中を進む姿は、時間までゆっくりと流れているように感じられます。\n\n![加西市の駅に停車する北条鉄道の緑色の列車](https://halimslife.com/images/blog/kasai-hojo-train-rural-station.webp)\n\n_加西市ののどかな駅に停車する、北条鉄道の緑色の一両列車。_'
      ),
      '車窓からは田園風景と、「加西アルプス」と呼ばれる善防山や笠松山を望むことができます。北条町周辺には、1300年以上の歴史を持つ住吉神社、酒見寺、独特な雰囲気を持つ **五百羅漢** などがあります。宿場町、門前町として栄えた街並みを歩くと、日本の古い時代の面影を感じることができます。',
      E'車窓からは田園風景と、「加西アルプス」と呼ばれる善防山や笠松山を望むことができます。北条町周辺には、1300年以上の歴史を持つ住吉神社、酒見寺、独特な雰囲気を持つ **五百羅漢** などがあります。宿場町、門前町として栄えた街並みを歩くと、日本の古い時代の面影を感じることができます。\n\n![北条町駅に並ぶ北条鉄道の列車](https://halimslife.com/images/blog/kasai-hojo-trains-hojomachi.webp)\n\n_北条町駅に並ぶ、北条鉄道の色鮮やかな列車。_'
    ),
    'こうしたことを知ると、あの日の散歩がまた違った光の中に見えてきます。最初はただの静かな地方都市の景色だと思っていた場所に、鉄道の物語、歴史、そして地域の人々の思いが重なっていました。加西市の観光情報は [Visit HYOGOの公式特集記事](https://www.hyogo-tourism.jp/world/feature/detail_109.html) でも詳しく紹介されています。',
    E'こうしたことを知ると、あの日の散歩がまた違った光の中に見えてきます。最初はただの静かな地方都市の景色だと思っていた場所に、鉄道の物語、歴史、そして地域の人々の思いが重なっていました。加西市の観光情報は [Visit HYOGOの公式特集記事](https://www.hyogo-tourism.jp/world/feature/detail_109.html) でも詳しく紹介されています。\n\n![加西市の駅に停車する北条鉄道の赤い列車](https://halimslife.com/images/blog/kasai-hojo-red-train-station.webp)\n\n_静かな加西の風景を走る北条鉄道の赤い列車。私にとって、このまちを象徴する親しみ深い景色です。_'
  ),
  updated_at = now()
where slug = 'bangladesh-flag-at-kasai-global-center-ja'
  and content not like '%kasai-global-center-interior.webp%';
